function Ring({ value, label }: { value: number; label: string }) {
  return <div className="ring" style={{ '--progress': `${value * 3.6}deg` } as React.CSSProperties}><div><strong>{value}{label === 'CGPA' ? '' : '%'}</strong><span>{label}</span></div></div>
}

function downloadFile(name: string, content: string) {
  const url = URL.createObjectURL(new Blob([content], { type: 'text/plain' }))
  const link = document.createElement('a'); link.href = url; link.download = name; link.click(); URL.revokeObjectURL(url)
}

const groups = [
  { label: 'Overview', items: [['dashboard', 'Dashboard', 'home'], ['timetable', 'Timetable', 'calendar'], ['attendance', 'Attendance', 'check']] },
  { label: 'Academics', items: [['courses', 'My Courses', 'book'], ['registration', 'Course Registration', 'plus'], ['add-drop', 'Add / Drop & Withdrawal', 'file'], ['results', 'Assessment Results', 'exam']] },
  { label: 'Examinations', items: [['exams', 'Seating Plan & Datesheet', 'calendar'], ['admit-card', 'Admit Card', 'file'], ['transcript', 'Unofficial Transcript', 'exam']] },
  { label: 'Finance', items: [['finance/ledger', 'General Ledger', 'wallet'], ['finance/vouchers', 'Fee Vouchers', 'file'], ['finance/payment', 'Payments', 'wallet']] },
  { label: 'Student Services', items: [['requests', 'Applications & Requests', 'file'], ['documents', 'Documents Vault', 'file'], ['notifications', 'Notifications', 'bell'], ['support', 'Support & FAQ', 'help']] },
  { label: 'Global Student', items: [['international', 'International Center', 'globe'], ['policies', 'Policies', 'book']] },
] as const

const pageTitles = Object.fromEntries(groups.flatMap(group => group.items.map(item => [item[0], item[1]])))

function useRoute() {
  const location = useLocation()
  const routerNavigate = useNavigate()
  const debugLayout = new URLSearchParams(location.search).get('debug') === 'layout'
  const route = location.pathname.replace(/^\/+/, '') || 'dashboard'
  const [loading, setLoading] = useState(false)
  useEffect(() => {
    if (debugLayout) { setLoading(false); return }
    setLoading(true)
    const timer = window.setTimeout(() => setLoading(false), 340)
    return () => window.clearTimeout(timer)
  }, [debugLayout, location.pathname])
  const navigate = (next: string) => {
    if (next === route) return
    routerNavigate(`/${next}`)
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }
  return { route, navigate, loading }
}

function Login({ state, update }: { state: PortalState; update: (fn: (s: PortalState) => PortalState) => void }) {
  const [kind, setKind] = useState<StudentKind>(state.activeKind), [roll, setRoll] = useState(state.students[state.activeKind].rollNo), [password, setPassword] = useState('uitdemo'), [show, setShow] = useState(false), [error, setError] = useState(''), [forgot, setForgot] = useState(false), [submitting, setSubmitting] = useState(false)
  const choose = (value: StudentKind) => { setKind(value); setRoll(state.students[value].rollNo); setPassword('uitdemo'); setError('') }
  const submit = (event: FormEvent) => {
    event.preventDefault()
    if (roll !== state.students[kind].rollNo) return setError(`Use ${state.students[kind].rollNo} for the ${kind} demo.`)
    if (password !== 'uitdemo') return setError('Incorrect demo password. Use “uitdemo”.')
    setError('')
    setSubmitting(true)
    window.setTimeout(() => update(current => ({ ...current, activeKind: kind, loggedIn: true })), 650)
  }
  if (forgot) return <main className="login"><section className="login-story"><Logo variant="onDark" /><div><span className="kicker">SECURE ACCOUNT RECOVERY</span><h1>Recover access with confidence.</h1><p>We will send verification instructions to your university email address.</p></div></section><section className="login-panel"><form className="auth-card" onSubmit={event => { event.preventDefault(); setForgot(false); setError('Recovery instructions sent to your UIT email.') }}><Button variant="ghost" onClick={() => setForgot(false)}>← Back to sign in</Button><h2>Forgot password?</h2><p>Enter your registered student ID.</p><label>Student ID<input value={roll} onChange={event => setRoll(event.target.value)} /></label>{error && <div className="form-message success">{error}</div>}<Button type="submit">Send recovery link <Icon name="arrow" size={17} /></Button></form></section></main>
  return <main className="login"><section className="login-story"><Logo variant="onDark" /><div><span className="kicker">UIT STUDENT EXPERIENCE</span><h1>Your academic journey, thoughtfully organized.</h1><p>A calm, secure home for courses, examinations, finances and every student service.</p><div className="trust-row"><span><Icon name="check" /> Secure access</span><span><Icon name="check" /> Live academic record</span><span><Icon name="globe" /> International ready</span></div></div><small>Usman Institute of Technology · Student Portal</small></section><section className="login-panel"><form className={`auth-card ${error ? 'shake' : ''}`} onSubmit={submit}><div className="mobile-logo"><Logo variant="full" /></div><span className="kicker">WELCOME BACK</span><h2>Sign in to your portal</h2><p>Choose a demo profile and use the credentials below.</p><div className="segment"><button type="button" className={kind === 'local' ? 'active' : ''} onClick={() => choose('local')}>Local student</button><button type="button" className={kind === 'international' ? 'active' : ''} onClick={() => choose('international')}>International student</button></div><label>Student ID<input value={roll} onChange={event => setRoll(event.target.value)} autoComplete="username" /></label><label>Password<div className="input-action"><input type={show ? 'text' : 'password'} value={password} onChange={event => setPassword(event.target.value)} autoComplete="current-password" /><button type="button" onClick={() => setShow(!show)} title={show ? 'Hide password' : 'Show password'} aria-label={show ? 'Hide password' : 'Show password'}><Icon name="eye" size={18} /></button></div></label><div className="form-row"><label className="check-label"><input type="checkbox" defaultChecked /> Remember me</label><button type="button" className="link" onClick={() => setForgot(true)}>Forgot password?</button></div>{error && <div className="form-message danger">{error}</div>}<Button type="submit" size="lg" loading={submitting}>Sign in securely <Icon name="arrow" size={17} /></Button><div className="demo-credentials"><strong>Demo credentials</strong><span>{state.students[kind].rollNo}</span><span>uitdemo</span></div><label className="language">Language<select defaultValue="English"><option>English</option><option>اردو</option></select></label></form></section></main>
}

function Shell({ state, update, reset }: { state: PortalState; update: (fn: (s: PortalState) => PortalState) => void; reset: () => void }) {
  const { route, navigate, loading } = useRoute()
  const [collapsed, setCollapsed] = useState(() => localStorage.getItem('uit-sidebar-collapsed') === 'true'), [mobile, setMobile] = useState(false), [command, setCommand] = useState(false), [notifications, setNotifications] = useState(false), [profile, setProfile] = useState(false), [toast, setToast] = useState(''), [query, setQuery] = useState(''), [online, setOnline] = useState(navigator.onLine)
  const student = state.students[state.activeKind]
  useEffect(() => {
    document.documentElement.dataset.density = state.preferences.density
  }, [state.preferences.density])
  useEffect(() => {
    const keys = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); setCommand(true) }
      if (event.key === '[' && !(event.target instanceof HTMLInputElement || event.target instanceof HTMLTextAreaElement)) setCollapsed(value => !value)
      if (event.key === 'Escape') { setCommand(false); setMobile(false); setNotifications(false); setProfile(false) }
    }
    window.addEventListener('keydown', keys); return () => window.removeEventListener('keydown', keys)
  }, [])
  useEffect(() => {
    localStorage.setItem('uit-sidebar-collapsed', String(collapsed))
  }, [collapsed])
  useEffect(() => {
    document.body.style.overflow = mobile ? 'hidden' : ''
    return () => { document.body.style.overflow = '' }
  }, [mobile])
  useEffect(() => {
    const connected = () => setOnline(true), disconnected = () => setOnline(false)
    window.addEventListener('online', connected); window.addEventListener('offline', disconnected)
    return () => { window.removeEventListener('online', connected); window.removeEventListener('offline', disconnected) }
  }, [])
  const announce = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 2600) }
  const searchIndex = useMemo(() => [
    ...Object.entries(pageTitles).map(([id, title]) => ({ id, title, meta: 'Page' })),
    ...state.courses.map(course => ({ id: 'courses', title: `${course.code} · ${course.title}`, meta: course.instructor })),
    ...state.announcements.map(item => ({ id: 'notifications', title: item.title, meta: 'Announcement' })),
    ...state.requests.map(item => ({ id: 'requests', title: item.type, meta: item.status })),
  ], [state])
  const found = searchIndex.filter(item => `${item.title} ${item.meta}`.toLowerCase().includes(query.toLowerCase())).slice(0, 8)
  const go = (id: string) => { navigate(id); setCommand(false); setQuery(''); setMobile(false) }
  const unread = state.notifications.filter(item => !item.read).length
  return <div className={`portal ${collapsed ? 'sidebar-collapsed' : ''}`}>
    <aside className={`sidebar ${mobile ? 'open' : ''}`} onDoubleClick={event => { if (event.target === event.currentTarget) setCollapsed(value => !value) }} aria-label="Portal navigation"><div className="sidebar-brand"><div className="sidebar-logo-morph"><Logo variant="full" /><Logo variant="mark" /></div><button className="sidebar-toggle" onClick={() => setCollapsed(!collapsed)} title={collapsed ? 'Expand sidebar  [' : 'Collapse sidebar  ['} aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'} aria-expanded={!collapsed}><Icon name="chevron" size={17} /></button></div><nav>{groups.map(group => <div className="nav-group" key={group.label}><span>{group.label}</span>{group.items.map(([id, label, icon]) => <button key={id} className={route === id ? 'active' : ''} onClick={() => go(id)} title={collapsed ? label : undefined}><Icon name={icon as IconName} /><b title={label}>{label}</b></button>)}</div>)}</nav><div className="sidebar-account"><button onClick={() => go('profile')}><span className="avatar">{student.name.split(' ').map(name => name[0]).slice(0, 2)}</span><b>{student.name}<small>{student.rollNo}</small></b></button></div></aside>
    {mobile && <button className="scrim" onClick={() => setMobile(false)} aria-label="Close navigation" />}
    <div className="workspace"><header className="topbar"><button className="mobile-menu" onClick={() => setMobile(true)} aria-label="Open menu"><Icon name="menu" /></button><Logo variant="mark" className="mobile-top-logo" /><div className="breadcrumb"><span>Student Portal</span><Icon name="chevron" size={14} /><strong>{pageTitles[route] || 'Page not found'}</strong></div><button className="top-search" onClick={() => setCommand(true)}><Icon name="search" size={17} /><span>Search portal</span><kbd>⌘ K</kbd></button><select className="semester-select" defaultValue="f26" onChange={() => announce('Semester context updated across the portal.')}><option value="f26">Fall 2026</option><option value="s26">Spring 2026</option></select><div className="popover-wrap"><button className="top-icon" onClick={() => setNotifications(!notifications)} title="Notifications" aria-label="Notifications" aria-expanded={notifications}><Icon name="bell" />{unread > 0 && <i>{unread}</i>}</button>{notifications && <div className="popover notification-popover"><div className="popover-head"><strong>Notifications</strong><button onClick={() => update(current => ({ ...current, notifications: current.notifications.map(item => ({ ...item, read: true })) }))}>Mark all read</button></div>{state.notifications.map(item => <button key={item.id} onClick={() => { go(item.route); setNotifications(false); update(current => ({ ...current, notifications: current.notifications.map(note => note.id === item.id ? { ...note, read: true } : note) })) }}><i className={item.read ? 'read' : ''} /><span><strong>{item.title}</strong><small>{item.body}</small></span><time>{item.time}</time></button>)}</div>}</div><div className="popover-wrap"><button className="profile-button" onClick={() => setProfile(!profile)} aria-label="Open profile menu" aria-expanded={profile}><span className="avatar">{student.name[0]}{student.name.split(' ')[1]?.[0]}</span><span>{student.name.split(' ')[0]}<small>{student.rollNo}</small></span><Icon name="chevron" size={14} /></button>{profile && <div className="popover profile-popover"><button onClick={() => { go('profile'); setProfile(false) }}>Student profile</button><button onClick={() => { go('settings'); setProfile(false) }}>Portal settings</button><button onClick={() => update(current => ({ ...current, loggedIn: false }))}>Sign out</button></div>}</div></header>
      {!online && <div className="offline-banner"><Icon name="alert" size={16} /><span>You are offline. Saved portal data remains available; submissions resume when connectivity returns.</span></div>}
      {state.activeKind === 'international' && (!student.insuranceValid || new Date(student.visaExpiry || '') < new Date('2027-01-31')) && <div className="global-alert"><Icon name="alert" size={17} /><span><strong>International compliance action required.</strong> Insurance proof or visa renewal must be completed before registration and admit-card release.</span><Button variant="text" onClick={() => go('international')}>Review now</Button></div>}
      <main className="content">{loading && <div className="route-progress" />}{loading ? <PageSkeleton /> : <Page route={route} state={state} update={update} navigate={go} announce={announce} reset={reset} />}</main>
      <nav className="bottom-nav">{[['dashboard','home','Home'],['courses','book','Courses'],['registration','plus','Register'],['finance/vouchers','wallet','Fees']].map(([id, icon, label]) => <button key={id} className={route === id ? 'active' : ''} onClick={() => go(id)}><Icon name={icon as IconName} /><span>{label}</span></button>)}<button onClick={() => setMobile(true)}><Icon name="menu" /><span>More</span></button></nav>
    </div>
    {command && <div className="overlay" onMouseDown={() => setCommand(false)}><section className="command" onMouseDown={event => event.stopPropagation()}><div><Icon name="search" /><input autoFocus value={query} onChange={event => setQuery(event.target.value)} placeholder="Search pages, courses, fees, requests…" /><kbd>ESC</kbd></div><span className="command-label">{query ? `${found.length} matches` : 'Quick navigation'}</span>{(query ? found : searchIndex.slice(0, 6)).map((item, index) => <button key={`${item.id}${index}`} onClick={() => go(item.id)}><Icon name={index % 2 ? 'file' : 'search'} size={17} /><span><strong>{item.title}</strong><small>{item.meta}</small></span><Icon name="arrow" size={16} /></button>)}</section></div>}
    {toast && <div className="toast" role="status"><Icon name="check" size={18} />{toast}</div>}
  </div>
}

function PageSkeleton() {
  return <div className="skeleton-page" aria-label="Loading page"><Logo variant="mark" /><div className="skeleton title" /><div className="skeleton-grid">{[1,2,3,4].map(item => <div className="skeleton card-skeleton" key={item} />)}</div><div className="skeleton table-skeleton" /></div>
}

function Page({ route, state, update, navigate, announce, reset }: { route: string; state: PortalState; update: (fn: (s: PortalState) => PortalState) => void; navigate: (id: string) => void; announce: (message: string) => void; reset: () => void }) {
  const props = { state, update, navigate, announce }
  if (route === 'dashboard') return <Dashboard {...props} />
  if (route === 'courses') return <Courses {...props} />
  if (route === 'timetable') return <Timetable {...props} />
  if (route === 'registration') return <Registration {...props} />
  if (route === 'add-drop') return <RequestsPage {...props} mode="Add / Drop & Withdrawal" />
  if (route === 'results') return <Results {...props} />
  if (route === 'exams') return <Exams {...props} />
  if (route === 'admit-card') return <AdmitCard {...props} />
  if (route === 'transcript') return <Transcript {...props} />
  if (route.startsWith('finance/')) return <Finance {...props} tab={route.split('/')[1]} />
  if (route === 'attendance') return <Attendance {...props} />
  if (route === 'requests') return <RequestsPage {...props} />
  if (route === 'documents') return <Documents {...props} />
  if (route === 'notifications') return <Notifications {...props} />
  if (route === 'support') return <Support {...props} />
  if (route === 'profile') return <Profile {...props} />
  if (route === 'settings') return <Settings {...props} reset={reset} />
  if (route === 'international') return <International {...props} />
  if (route === 'policies') return <Policies {...props} />
  return <NotFound navigate={navigate} />
}

type PageProps = { state: PortalState; update: (fn: (s: PortalState) => PortalState) => void; navigate: (id: string) => void; announce: (message: string) => void }
function PageHeader({ eyebrow, title, copy, actions }: { eyebrow: string; title: string; copy: string; actions?: ReactNode }) {
  return <header className="page-header"><div><span className="kicker">{eyebrow}</span><h1>{title}</h1><p>{copy}</p></div>{actions && <div className="page-actions">{actions}</div>}</header>
}

function Dashboard({ state, navigate }: PageProps) {
  const student = state.students[state.activeKind], due = state.vouchers.filter(item => item.status === 'due').reduce((sum, item) => sum + item.amount, 0), attendance = Math.round(state.courses.reduce((sum, item) => sum + item.attendance, 0) / state.courses.length)
  return <>
    <section className="dashboard-hero">
      <div className="hero-copy"><span className="hero-date">SUNDAY · 01 NOVEMBER 2026</span><h1>Good morning, {student.name.split(' ')[0]}.</h1><p>Your academic week is moving well. Here is the signal, not the noise.</p><div className="hero-actions"><Button onClick={() => navigate('timetable')}><Icon name="calendar" size={17} /> View today’s plan</Button><button onClick={() => navigate('notifications')}>2 updates need attention <Icon name="arrow" size={15} /></button></div></div>
      <div className="hero-academic"><Ring value={student.cgpa} label="CGPA" /><div><span>Academic standing</span><strong>{student.status}</strong><small>+0.08 this academic year</small></div></div>
      <div className="hero-watermark">UIT</div>
    </section>
    <div className="dashboard-intro"><div><span className="kicker">SEMESTER AT A GLANCE</span><h2>Fall 2026</h2></div><span>Week 10 of 16 · 18 registered credit hours</span></div>
    <div className="stats refined-stats"><Stat title="Average attendance" value={`${attendance}%`} note="CS-401 requires attention" tone="teal" onClick={() => navigate('attendance')} /><Stat title="Degree progress" value="90 / 124" note="72% of credits completed" tone="indigo" onClick={() => navigate('transcript')} /><Stat title="Outstanding fee" value={money(due)} note="Due 14 November 2026" tone="amber" onClick={() => navigate('finance/vouchers')} /></div>
    <div className="dashboard-grid">
      <Card className="schedule-card"><SectionHead kicker="TODAY · MONDAY" title="Your day, in sequence" action="Open timetable" onClick={() => navigate('timetable')} />{state.courses.filter(item => item.days.includes('Mon')).map((course, index) => <button className="schedule-row" key={course.code} onClick={() => navigate('courses')}><span className={`course-dot ${course.color}`} /><time>{course.time}</time><span><strong title={course.title}>{course.title}</strong><small title={`${course.code} · ${course.instructor}`}>{course.code} · {course.instructor}</small></span><em><Icon name="pin" size={14} />{course.room}</em><span className="class-order">0{index + 1}</span></button>)}</Card>
      <div className="dashboard-side"><Card className="attention-card"><SectionHead kicker="ACTION CENTER" title="Needs your attention" /><button onClick={() => navigate('attendance')}><span className="alert-icon warning"><Icon name="alert" /></span><span><strong>Attendance shortage</strong><small>CS-401 is at 74%; minimum is 75%.</small></span><Icon name="arrow" size={16} /></button><button onClick={() => navigate('finance/vouchers')}><span className="alert-icon info"><Icon name="wallet" /></span><span><strong>Fee voucher due</strong><small>{money(due)} due by November 14.</small></span><Icon name="arrow" size={16} /></button>{state.activeKind === 'international' && <button onClick={() => navigate('international')}><span className="alert-icon danger"><Icon name="globe" /></span><span><strong>Insurance proof missing</strong><small>Required before admit-card release.</small></span><Icon name="arrow" size={16} /></button>}</Card><Card className="quick-actions"><SectionHead kicker="SHORTCUTS" title="Quick actions" /><div>{[['Pay fee','finance/payment','wallet'],['Register','registration','plus'],['Request','requests','file'],['Support','support','help']].map(([label, route, icon]) => <button key={label} onClick={() => navigate(route)}><span><Icon name={icon as IconName} /></span>{label}</button>)}</div></Card></div>
    </div>
    <div className="dashboard-lower"><Card><SectionHead kicker="ACADEMIC PERFORMANCE" title="GPA trajectory" action="View transcript" onClick={() => navigate('transcript')} /><LineChart values={state.semesters.slice(0, 7).map(item => item.gpa)} labels={state.semesters.slice(0, 7).map(item => item.label.split(' ')[0][0] + item.label.slice(-2))} /></Card><Card><SectionHead kicker="CAMPUS DESK" title="Announcements" action="View all" onClick={() => navigate('notifications')} />{state.announcements.map(item => <button className="announcement-row" key={item.id} onClick={() => navigate('notifications')}><time>{new Date(item.date).toLocaleDateString('en', { day: '2-digit', month: 'short' })}</time><span><strong>{item.title}</strong><small>{item.body}</small></span></button>)}</Card><GpaSimulator current={student.cgpa} /></div>
  </>
}

function Stat({ title, value, note, tone, onClick }: { title: string; value: string; note: string; tone: string; onClick: () => void }) {
  return <Card className={`stat ${tone}`} onClick={onClick}><span>{title}</span><strong>{value}</strong><small>{note}</small><div className="spark">{[2,4,3,6,5,8,7].map((height, index) => <i key={index} style={{ height: height * 3 }} />)}</div></Card>
}
function GpaSimulator({ current }: { current: number }) {
  const [target, setTarget] = useState(3.5)
  const projected = ((current * 90 + target * 18) / 108).toFixed(2)
  return <Card className="gpa-simulator"><SectionHead kicker="GPA WHAT-IF" title="Project your CGPA" /><div className="simulator-result"><span>Projected CGPA</span><strong>{projected}</strong></div><label htmlFor="gpa-target">Expected semester GPA <b>{target.toFixed(1)}</b></label><input id="gpa-target" type="range" min="2" max="4" step=".1" value={target} onChange={event => setTarget(Number(event.target.value))} /><div className="range-labels"><span>2.0</span><span>4.0</span></div></Card>
}
function SectionHead({ kicker, title, action, onClick }: { kicker: string; title: string; action?: string; onClick?: () => void }) {
  return <div className="section-head"><div><span className="kicker">{kicker}</span><h2>{title}</h2></div>{action && <Button variant="text" onClick={onClick}>{action}<Icon name="arrow" size={15} /></Button>}</div>
}
function LineChart({ values, labels }: { values: number[]; labels: string[] }) {
  const points = values.map((value, index) => `${(index / (values.length - 1)) * 100},${90 - ((value - 2.5) / 1.5) * 75}`).join(' ')
  return <div className="line-chart"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="var(--brand-500)" stopOpacity=".24" /><stop offset="1" stopColor="var(--brand-500)" stopOpacity="0" /></linearGradient></defs><polygon points={`0,100 ${points} 100,100`} fill="url(#fill)" /><polyline points={points} fill="none" stroke="var(--brand-500)" strokeWidth="2" vectorEffect="non-scaling-stroke" /></svg><div>{labels.map((label, index) => <span key={label}><b>{values[index].toFixed(2)}</b>{label}</span>)}</div></div>
}

function Courses({ state }: PageProps) {
  const [view, setView] = useState<'grid' | 'list'>('grid'), [filter, setFilter] = useState('All'), [selected, setSelected] = useState<Course | null>(null), [tab, setTab] = useState('Overview')
  useEffect(() => {
    if (!selected) return
    const close = (event: KeyboardEvent) => { if (event.key === 'Escape') setSelected(null) }
    window.addEventListener('keydown', close)
    return () => window.removeEventListener('keydown', close)
  }, [selected])
  const shown = state.courses.filter(item => filter === 'All' || (filter === 'Attention' ? item.attendance < 75 : item.days.includes(filter)))
  return <><PageHeader eyebrow="FALL 2026 · 18 CREDIT HOURS" title="My Courses" copy="Coursework, attendance, marks and learning materials in one place." actions={<><select value={filter} onChange={event => setFilter(event.target.value)}><option>All</option><option>Mon</option><option>Thu</option><option>Attention</option></select><div className="icon-segment"><button className={view === 'grid' ? 'active' : ''} onClick={() => setView('grid')}>Grid</button><button className={view === 'list' ? 'active' : ''} onClick={() => setView('list')}>List</button></div></>} /><div className={`course-grid ${view}`}>{shown.map(course => <Card className="course-card" key={course.code} onClick={() => setSelected(course)}><div className="course-top"><Badge tone={course.color}>{course.code}</Badge><Badge tone={course.attendance < 75 ? 'danger' : 'success'}>{course.attendance}% attendance</Badge></div><h3>{course.title}</h3><p>{course.instructor}</p><div className="course-facts"><span><Icon name="clock" size={15} />{course.days.join(' · ')} · {course.time}</span><span><Icon name="pin" size={15} />{course.room}</span></div><div className="progress"><i style={{ width: `${course.attendance}%` }} /></div><footer><span>{course.credits} credit hours</span><strong>Grade {course.grade}</strong></footer></Card>)}</div>{selected && <div className="drawer-backdrop" onMouseDown={() => setSelected(null)}><aside className="drawer" onMouseDown={event => event.stopPropagation()}><div className="drawer-head"><Badge tone={selected.color}>{selected.code}</Badge><CloseButton onClick={() => setSelected(null)} label="Close course details" /></div><h2>{selected.title}</h2><p>{selected.instructor} · {selected.room}</p><div className="tabs">{['Overview','Marks','Attendance','Materials'].map(item => <button className={tab === item ? 'active' : ''} onClick={() => setTab(item)} key={item}>{item}</button>)}</div>{tab === 'Overview' && <div className="drawer-section"><div className="detail-grid"><span><small>Schedule</small><strong>{selected.days.join(', ')} · {selected.time}</strong></span><span><small>Credit hours</small><strong>{selected.credits}</strong></span><span><small>Current grade</small><strong>{selected.grade}</strong></span><span><small>Attendance</small><strong>{selected.attendance}%</strong></span></div><h3>Instructor</h3><div className="instructor"><span className="avatar">{selected.instructor.split(' ').map(item => item[0]).slice(0,2)}</span><span><strong>{selected.instructor}</strong><small>Office hours · Tue 12:00–14:00</small></span><Button variant="secondary" onClick={() => location.href = `mailto:${selected.instructor.toLowerCase().replace(/ /g, '.')}@uit.edu`}>Email</Button></div></div>}{tab === 'Marks' && <Marks course={selected} />}{tab === 'Attendance' && <AttendanceCalendar percent={selected.attendance} />}{tab === 'Materials' && <div className="material-list">{['Course outline.pdf','Lecture slides — Week 08.pdf','Assignment 03 brief.pdf'].map(name => <button key={name} onClick={() => downloadFile(name, `${selected.code} · ${name}`)}><Icon name="file" /><span><strong>{name}</strong><small>PDF · Course resource</small></span><Icon name="download" /></button>)}</div>}</aside></div>}</>
}
function Marks({ course }: { course: Course }) {
  const total = Object.values(course.marks).reduce((sum, mark) => sum + mark, 0)
  return <div className="marks"><div className="marks-total"><Ring value={total} label="Total" /><div><strong>{total} / 110</strong><span>Current weighted score</span></div></div>{Object.entries(course.marks).map(([name, value]) => <div key={name}><span>{name}</span><div className="progress"><i style={{ width: `${value * 2}%` }} /></div><strong>{value}</strong></div>)}</div>
}
function AttendanceCalendar({ percent }: { percent: number }) {
  return <div><div className="attendance-summary"><strong>{percent}%</strong><span>{percent >= 75 ? 'Eligible for examination' : 'Attendance shortage'}</span></div><div className="mini-calendar">{Array.from({ length: 30 }, (_, index) => <span className={index % 7 === 0 ? 'absent' : index % 5 === 0 ? 'leave' : 'present'} key={index}>{index + 1}</span>)}</div><div className="legend"><i className="present" />Present <i className="absent" />Absent <i className="leave" />Leave</div></div>
}

function Timetable({ state, announce, navigate }: PageProps) {
  const [view, setView] = useState('Week'), days = ['Mon','Tue','Wed','Thu','Fri','Sat']
  return <><PageHeader eyebrow="FALL 2026" title="Timetable" copy="A conflict-free view of your weekly academic schedule." actions={<><div className="icon-segment"><button className={view === 'Week' ? 'active' : ''} onClick={() => setView('Week')}>Week</button><button className={view === 'Day' ? 'active' : ''} onClick={() => setView('Day')}>Day</button></div><Button variant="secondary" onClick={() => { downloadFile('UIT-Fall-2026-Timetable.ics', 'BEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//UIT//Portal//EN\nEND:VCALENDAR'); announce('Calendar file generated and downloaded.') }}><Icon name="download" size={16} /> Export</Button></>} />{view === 'Week' ? <div className="week-grid">{days.map(day => <div key={day}><header>{day}<small>{day === 'Mon' ? 'Today' : ''}</small></header>{state.courses.filter(course => course.days.includes(day)).map(course => <button className={`class-block ${course.color}`} key={course.code} onClick={() => navigate('courses')}><strong>{course.code}</strong><span>{course.title}</span><small>{course.time}</small><small>{course.room}</small></button>)}</div>)}</div> : <Card className="day-view"><SectionHead kicker="MONDAY · TODAY" title="3 scheduled sessions" />{state.courses.filter(course => course.days.includes('Mon')).map(course => <button className="day-row" key={course.code} onClick={() => navigate('courses')}><time>{course.time}</time><i className={course.color} /><span><strong>{course.title}</strong><small>{course.instructor} · {course.room}</small></span></button>)}</Card>}</>
}

function Registration({ state, update, announce, navigate }: PageProps) {
  const [cart, setCart] = useState<string[]>(state.registered), [step, setStep] = useState(1), student = state.students[state.activeKind]
  const internationalBlocked = state.activeKind === 'international' && (!student.insuranceValid || new Date(student.visaExpiry || '') < new Date(state.policies.semesterEnd))
  const credits = cart.reduce((sum, code) => sum + (state.courses.find(course => course.code === code)?.credits || 0), 0)
  const toggle = (course: Course) => {
    if (cart.includes(course.code)) setCart(cart.filter(code => code !== course.code))
    else if (credits + course.credits > state.policies.maxCredits) announce(`Credit cap is ${state.policies.maxCredits}. Remove a course before adding ${course.code}.`)
    else setCart([...cart, course.code])
  }
  if (internationalBlocked) return <><PageHeader eyebrow="REGISTRATION HOLD" title="Course Registration" copy="International compliance must be resolved before registration." /><Card className="blocked-state"><span className="alert-icon danger"><Icon name="alert" size={28} /></span><h2>Registration is temporarily blocked</h2><p>Your health insurance proof is missing or your visa does not remain valid through the semester. Upload proof or submit a renewal request.</p><Button onClick={() => navigate('international')}>Resolve compliance hold <Icon name="arrow" size={16} /></Button></Card></>
  return <><PageHeader eyebrow="FALL 2026 · OPEN UNTIL 12 NOV" title="Course Registration" copy={`Select ${state.policies.minCredits}–${state.policies.maxCredits} credits. Prerequisites and schedule clashes are checked automatically.`} /><div className="stepper">{['Select courses','Review plan','Confirmation'].map((label, index) => <span className={step >= index + 1 ? 'active' : ''} key={label}><i>{step > index + 1 ? <Icon name="check" size={14} /> : index + 1}</i>{label}</span>)}</div>{step === 1 && <div className="registration-layout"><div className="registration-courses">{state.courses.map(course => <Card key={course.code} className={cart.includes(course.code) ? 'selected-course' : ''}><div><Badge tone={course.color}>{course.code}</Badge><Badge tone="neutral">{course.credits} credits</Badge></div><h3>{course.title}</h3><p>{course.instructor} · {course.days.join(', ')} {course.time}</p>{course.prerequisite && <small>Prerequisite verified: {course.prerequisite}</small>}<Button variant={cart.includes(course.code) ? 'secondary' : 'primary'} onClick={() => toggle(course)}>{cart.includes(course.code) ? 'Remove from plan' : 'Add to plan'}</Button></Card>)}</div><Card className="cart"><SectionHead kicker="YOUR PLAN" title={`${credits} / ${state.policies.maxCredits} credits`} />{cart.map(code => <span key={code}>{code}<button onClick={() => setCart(cart.filter(item => item !== code))}><Icon name="close" size={14} /></button></span>)}{credits < state.policies.minCredits && <div className="inline-warning"><Icon name="alert" size={16} />Minimum full-time load is {state.policies.minCredits} credits.</div>}<Button disabled={credits < state.policies.minCredits} onClick={() => setStep(2)}>Review plan <Icon name="arrow" size={16} /></Button></Card></div>}{step === 2 && <Card className="review-card"><SectionHead kicker="STEP 2 OF 3" title="Review your semester plan" /><DataTable headers={['Course','Title','Credits','Schedule']} rows={cart.map(code => { const course = state.courses.find(item => item.code === code)!; return [course.code,course.title,String(course.credits),`${course.days.join(', ')} ${course.time}`] })} /><label className="policy-check"><input type="checkbox" checked={state.acknowledgements.integrity} onChange={event => update(current => ({ ...current, acknowledgements: { ...current.acknowledgements, integrity: event.target.checked } }))} />I acknowledge the academic integrity and plagiarism policy.</label><div className="review-actions"><Button variant="secondary" onClick={() => setStep(1)}>Back</Button><Button disabled={!state.acknowledgements.integrity} onClick={() => { update(current => ({ ...current, registered: cart })); setStep(3) }}>Confirm registration</Button></div></Card>}{step === 3 && <Card className="success-state"><span><Icon name="check" size={28} /></span><h2>Registration confirmed</h2><p>Your Fall 2026 plan has been saved across the portal.</p><strong>{credits} credit hours · {cart.length} courses</strong><div><Button variant="secondary" onClick={() => downloadFile('UIT-registration-receipt.txt', `UIT Registration Receipt\n${student.rollNo}\n${cart.join('\n')}\nTotal: ${credits} credits`)}><Icon name="download" size={16} /> Download receipt</Button><Button onClick={() => navigate('dashboard')}>Return to dashboard</Button></div></Card>}</>
}

function DataTable({ headers, rows }: { headers: string[]; rows: string[][] }) {
  const [sort, setSort] = useState(0), [asc, setAsc] = useState(true), [filter, setFilter] = useState(''), [page, setPage] = useState(1)
  const shown = rows.filter(row => row.join(' ').toLowerCase().includes(filter.toLowerCase())).sort((a,b) => asc ? a[sort].localeCompare(b[sort], undefined, { numeric: true }) : b[sort].localeCompare(a[sort], undefined, { numeric: true }))
  const pageRows = shown.slice((page - 1) * 6, page * 6)
  return <div className="table-component"><div className="table-tools"><div><Icon name="search" size={16} /><input value={filter} onChange={event => { setFilter(event.target.value); setPage(1) }} placeholder="Filter records…" /></div><span>{shown.length} records</span></div><div className="table-scroll"><table><thead><tr>{headers.map((header,index) => <th key={header}><button onClick={() => { if (sort === index) setAsc(!asc); else { setSort(index); setAsc(true) } }}>{header}{sort === index && <span>{asc ? '↑' : '↓'}</span>}</button></th>)}</tr></thead><tbody>{pageRows.length ? pageRows.map((row,index) => <tr key={index}>{row.map((cell,cellIndex) => <td key={cellIndex}>{cell}</td>)}</tr>) : <tr><td colSpan={headers.length}><Empty title="No matching records" copy="Try a different filter." /></td></tr>}</tbody></table></div>{shown.length > 6 && <div className="pagination"><Button variant="ghost" disabled={page === 1} onClick={() => setPage(page - 1)}>Previous</Button><span>Page {page} of {Math.ceil(shown.length / 6)}</span><Button variant="ghost" disabled={page >= Math.ceil(shown.length / 6)} onClick={() => setPage(page + 1)}>Next</Button></div>}</div>
}
function Empty({ title, copy }: { title: string; copy: string }) { return <div className="empty"><Icon name="search" /><strong>{title}</strong><span>{copy}</span></div> }

function Results({ state, announce }: PageProps) {
  const rows = state.courses.map(course => [course.code, course.title, String(course.marks.quiz), String(course.marks.assignment), String(course.marks.midterm), String(course.marks.final), String(course.marks.project), course.grade])
  return <><PageHeader eyebrow="EXAMINATION OFFICE" title="Assessment Results" copy="Component-level results with transparent grade calculations." actions={<Button variant="secondary" onClick={() => { downloadFile('UIT-result-card.txt', rows.map(row => row.join('\t')).join('\n')); announce('Result card downloaded.') }}><Icon name="download" size={16} /> Result card</Button>} /><div className="result-summary"><Card><span>Semester GPA</span><strong>3.36</strong><small>Class average 3.08</small></Card><Card><span>Highest grade</span><strong>A</strong><small>Information Security</small></Card><Card><span>Credits assessed</span><strong>18</strong><small>6 courses</small></Card></div><Card className="table-card"><DataTable headers={['Code','Course','Quiz','Assignment','Midterm','Final','Project','Grade']} rows={rows} /></Card></>
}

function Exams({ state, announce }: PageProps) {
  const [tab, setTab] = useState('Datesheet')
  const examRows = state.courses.map((course,index) => [`${21 + index} Nov 2026`, index % 2 ? '13:30–15:30' : '09:00–11:00', course.code, course.title, `Hall ${String.fromCharCode(65 + index % 3)}`, `Seat ${12 + index}`])
  return <><PageHeader eyebrow="MIDTERM EXAMINATIONS · FALL 2026" title="Seating Plan & Datesheet" copy="Official examination schedule and assigned seating." actions={<Button variant="secondary" onClick={() => { downloadFile('UIT-midterm-datesheet.txt', examRows.map(row => row.join('\t')).join('\n')); announce('Datesheet downloaded.') }}><Icon name="download" size={16} /> Export datesheet</Button>} /><div className="tabs page-tabs">{['Datesheet','Seat map','Instructions'].map(item => <button className={tab === item ? 'active' : ''} onClick={() => setTab(item)} key={item}>{item}</button>)}</div>{tab === 'Datesheet' && <Card className="table-card"><DataTable headers={['Date','Time','Code','Course','Venue','Seat']} rows={examRows} /></Card>}{tab === 'Seat map' && <Card className="seat-plan"><div className="seat-ticket"><span>HALL</span><strong>A</strong><span>ROW / SEAT</span><strong>2 / 14</strong></div><div><SectionHead kicker="YOUR ASSIGNMENT" title="Computing Block · Hall A" /><p>Enter through the east corridor and report 30 minutes before the examination.</p><div className="seat-grid">{Array.from({ length: 30 }, (_,index) => <span className={index === 13 ? 'mine' : ''} key={index}>{index + 1}</span>)}</div></div></Card>}{tab === 'Instructions' && <Card className="policy-copy"><h2>Examination room protocol</h2><ol><li>Bring your printed admit card and original student ID.</li><li>Report at least 30 minutes before the scheduled start.</li><li>Electronic devices are not permitted unless explicitly authorized.</li><li>Follow the invigilator’s seating and submission instructions.</li></ol></Card>}</>
}

function AdmitCard({ state, navigate, announce }: PageProps) {
  const student = state.students[state.activeKind], due = state.vouchers.some(item => item.status === 'due'), attendanceHold = state.courses.some(item => item.attendance < state.policies.attendanceMinimum), internationalHold = state.activeKind === 'international' && !student.insuranceValid, blocked = due || attendanceHold || internationalHold
  return <><PageHeader eyebrow="FALL 2026 MIDTERM" title="Admit Card" copy="Exam eligibility is checked against fees, attendance and compliance rules." />{blocked ? <Card className="blocked-state"><span className="alert-icon danger"><Icon name="alert" size={28} /></span><h2>Admit card has eligibility holds</h2><p>Resolve every item below. Eligibility updates instantly across the portal.</p><div className="hold-list">{due && <ListRow leading={<Icon name="wallet" />} title="Outstanding semester dues" description="Pay voucher FV-26091 to clear this hold." trailing={<Icon name="arrow" />} onClick={() => navigate('finance/payment')} />}{attendanceHold && <ListRow leading={<Icon name="check" />} title="Attendance below 75%" description="CS-401 requires an approved shortage waiver." trailing={<Icon name="arrow" />} onClick={() => navigate('attendance')} />}{internationalHold && <ListRow leading={<Icon name="globe" />} title="Health insurance proof missing" description="Upload verified coverage before admit-card release." trailing={<Icon name="arrow" />} onClick={() => navigate('international')} />}</div></Card> : <PrintableDocument title="EXAMINATION ADMIT CARD" student={student} action={() => { window.print(); announce('Print dialog opened for the admit card.') }}><div className="qr">UIT<br />{student.rollNo}</div><DataTable headers={['Date','Time','Course','Venue','Seat']} rows={state.courses.map((course,index) => [`${21+index} Nov`, index%2?'13:30':'09:00',course.code,`Hall ${String.fromCharCode(65+index%3)}`,String(14+index)])} /></PrintableDocument>}</>
}

function PrintableDocument({ title, student, children, action }: { title: string; student: PortalState['students']['local']; children: ReactNode; action: () => void }) {
  return <Card className="print-document"><header><Logo variant="full" /><div><span>UIT UNIVERSITY</span><h2>{title}</h2><small>Official student record · Generated 01 Nov 2026</small></div><Button variant="secondary" onClick={action}><Icon name="download" size={16} /> Print / Save PDF</Button></header><div className="document-student"><span className="avatar large">{student.name.split(' ').map(item => item[0]).slice(0,2)}</span><div><strong>{student.name}</strong><small>{student.rollNo} · {student.program} · Section {student.section}</small></div><Badge tone="success">Verified</Badge></div>{children}<footer><Logo variant="mark" /><span>Digitally generated by UIT Student Portal</span></footer></Card>
}

function Transcript({ state, announce }: PageProps) {
  const student = state.students[state.activeKind], rows = state.semesters.map(item => [item.label,String(item.credits),item.gpa ? item.gpa.toFixed(2) : 'Planned',item.status])
  return <><PageHeader eyebrow="ACADEMIC RECORD" title="Unofficial Transcript" copy="Eight-semester academic history with transparent GPA progression." /><PrintableDocument title="UNOFFICIAL TRANSCRIPT" student={student} action={() => { downloadFile('UIT-unofficial-transcript.txt', rows.map(row => row.join('\t')).join('\n')); announce('Transcript downloaded.') }}><div className="transcript-summary"><span><small>Cumulative GPA</small><strong>{student.cgpa.toFixed(2)}</strong></span><span><small>Credits earned</small><strong>90</strong></span><span><small>Academic standing</small><strong>{student.status}</strong></span></div><LineChart values={state.semesters.filter(item => item.gpa).map(item => item.gpa)} labels={state.semesters.filter(item => item.gpa).map(item => item.label.slice(0,3))} /><DataTable headers={['Semester','Credits','GPA','Status']} rows={rows} /></PrintableDocument></>
}

function Finance({ state, update, announce, navigate, tab }: PageProps & { tab: string }) {
  const [paymentStep, setPaymentStep] = useState(1), [method, setMethod] = useState('Card'), due = state.vouchers.find(item => item.status === 'due')
  const pay = () => {
    if (!due) return
    update(current => ({ ...current, vouchers: current.vouchers.map(item => item.id === due.id ? { ...item, status: 'paid' } : item), ledger: [{ id: `L${Date.now()}`, date: '2026-11-01', description: `Online payment — ${method}`, debit: 0, credit: due.amount, balance: 0 }, ...current.ledger], notifications: [{ id: `N${Date.now()}`, title: 'Payment successful', body: `${money(due.amount)} received for ${due.id}.`, time: 'Now', read: false, route: 'finance/ledger' }, ...current.notifications] }))
    setPaymentStep(3)
  }
  if (tab === 'ledger') return <><PageHeader eyebrow="STUDENT FINANCE" title="General Ledger" copy="A reconciled record of charges, payments and current balance." actions={<Button variant="secondary" onClick={() => downloadFile('UIT-ledger.txt', state.ledger.map(item => Object.values(item).join('\t')).join('\n'))}><Icon name="download" size={16} /> Statement</Button>} /><Card className="balance-card"><div><span>Current balance</span><strong>{money(state.vouchers.filter(item => item.status === 'due').reduce((sum,item)=>sum+item.amount,0))}</strong><small>Includes all posted charges and payments</small></div><Button onClick={() => navigate('finance/payment')}>Make a payment</Button></Card><Card className="table-card"><DataTable headers={['Date','Description','Debit','Credit','Balance']} rows={state.ledger.map(item => [item.date,item.description,money(item.debit),money(item.credit),money(item.balance)])} /></Card></>
  if (tab === 'vouchers') return <><PageHeader eyebrow="STUDENT FINANCE" title="Fee Vouchers" copy="View, download and pay university fee vouchers." />{state.activeKind === 'international' && <div className="international-fee"><Icon name="globe" /><span><strong>International tuition schedule</strong><small>USD 2,100 · PKR 588,000 equivalent at the published university rate · {state.policies.lateFeePercent}% late fee after due date</small></span><Badge tone="info">USD / PKR</Badge></div>}<div className="voucher-grid">{state.vouchers.map(item => <Card className="voucher" key={item.id}><header><Badge tone={item.status === 'paid' ? 'success' : 'warning'}>{item.status}</Badge><span>{item.id}</span></header><h3>{item.title}</h3><strong>{money(item.amount,item.currency)}</strong><p>Due {new Date(item.due).toLocaleDateString('en',{day:'numeric',month:'long',year:'numeric'})}</p><footer><Button variant="secondary" onClick={() => downloadFile(`${item.id}.txt`,`UIT FEE VOUCHER\n${item.id}\n${item.title}\n${money(item.amount)}`)}><Icon name="download" size={16} /> Download</Button>{item.status === 'due' && <Button onClick={() => navigate('finance/payment')}>Pay now</Button>}</footer></Card>)}</div></>
  return <><PageHeader eyebrow="SECURE MOCK GATEWAY" title="Payment" copy="Complete a simulated payment; balances and eligibility update instantly." />{!due ? <Card className="success-state"><span><Icon name="check" /></span><h2>No outstanding balance</h2><p>All posted vouchers have been paid.</p><Button variant="secondary" onClick={() => downloadFile('UIT-payment-receipt.txt','UIT University\nAccount paid in full')}>Download latest receipt</Button></Card> : <Card className="payment-flow"><div className="stepper">{['Method','Confirm','Receipt'].map((item,index) => <span className={paymentStep >= index+1 ? 'active' : ''} key={item}><i>{index+1}</i>{item}</span>)}</div>{paymentStep === 1 && <div className="payment-methods"><h2>Select payment method</h2>{['Card','Bank transfer','Mobile wallet'].map(item => <label className={method === item ? 'selected' : ''} key={item}><input type="radio" name="method" checked={method === item} onChange={() => setMethod(item)} /><Icon name="wallet" /><span><strong>{item}</strong><small>Secure simulated payment</small></span></label>)}<Button onClick={() => setPaymentStep(2)}>Continue to confirmation</Button></div>}{paymentStep === 2 && <div className="payment-confirm"><h2>Confirm your payment</h2><div><span>Voucher</span><strong>{due.id}</strong><span>Method</span><strong>{method}</strong><span>Amount</span><strong>{money(due.amount)}</strong></div><p>No real charge will be made. This is a front-end demonstration.</p><Button variant="secondary" onClick={() => setPaymentStep(1)}>Back</Button><Button onClick={pay}>Confirm payment</Button></div>}{paymentStep === 3 && <div className="success-state"><span><Icon name="check" /></span><h2>Payment successful</h2><p>Your ledger, voucher, dashboard balance and admit-card eligibility were updated.</p><strong>{money(due.amount)}</strong><Button variant="secondary" onClick={() => { downloadFile(`UIT-${due.id}-receipt.txt`,`UIT PAYMENT RECEIPT\n${due.id}\n${money(due.amount)}\nPaid via ${method}`); announce('Payment receipt downloaded.') }}>Download receipt</Button></div>}</Card>}</>
}

function Attendance({ state, update, announce }: PageProps) {
  const [leave, setLeave] = useState(false)
  return <><PageHeader eyebrow="FALL 2026" title="Attendance" copy={`Minimum ${state.policies.attendanceMinimum}% attendance is required for exam eligibility.`} actions={<Button onClick={() => setLeave(true)}><Icon name="plus" size={16} /> Apply for leave</Button>} /><div className="attendance-grid">{state.courses.map(course => <Card key={course.code} className={course.attendance < 75 ? 'shortage' : ''}><Ring value={course.attendance} label="Attendance" /><div><Badge tone={course.attendance < 75 ? 'danger' : 'success'}>{course.attendance < 75 ? 'Shortage' : 'Eligible'}</Badge><h3>{course.title}</h3><p>{course.code} · {course.instructor}</p><small>{Math.round(course.attendance*.22)} present · {Math.round((100-course.attendance)*.22)} absent</small></div></Card>)}</div>{leave && <FormDialog title="Leave application" onClose={() => setLeave(false)} onSubmit={() => { update(current => ({ ...current, requests: [{ id:`REQ-${Date.now()}`,type:'Attendance leave',submitted:'2026-11-01',status:'pending',note:'With course instructor' },...current.requests] })); setLeave(false); announce('Leave application submitted and added to Requests.') }} fields={['Course','From date','To date','Reason']} />}</>
}

function RequestsPage({ state, update, announce, mode }: PageProps & { mode?: string }) {
  const [form, setForm] = useState(false), types = mode ? ['Add course','Drop course','Semester withdrawal'] : ['NOC','Bonafide certificate','Degree verification','Course re-check','Repeat / improve']
  return <><PageHeader eyebrow="STUDENT SERVICES" title={mode || 'Applications & Requests'} copy={mode ? 'Deadline-aware academic enrollment changes with enforced rules.' : 'Submit and track official student service requests.'} actions={<Button onClick={() => setForm(true)}><Icon name="plus" size={16} /> New request</Button>} />{mode && <div className="deadline-banner"><Icon name="clock" /><span><strong>Add/drop closes November 08</strong><small>Withdrawal requests remain open until November 28 and receive a W grade.</small></span></div>}<div className="request-layout"><div className="request-types">{types.map((type,index) => <Card key={type} onClick={() => setForm(true)}><span>0{index+1}</span><div><strong>{type}</strong><small>Review rules and start application</small></div><Icon name="arrow" /></Card>)}</div><Card className="request-history"><SectionHead kicker="YOUR ACTIVITY" title="Request tracker" />{state.requests.map(item => <ListRow key={item.id} leading={<i className={`request-status ${item.status}`} />} title={item.type} description={`${item.id} · Submitted ${item.submitted} · ${item.note}`} trailing={<Badge tone={statusTone(item.status)}>{item.status}</Badge>} />)}</Card></div>{form && <FormDialog title={mode ? 'Enrollment change request' : 'New application'} onClose={() => setForm(false)} onSubmit={() => { update(current => ({ ...current, requests: [{ id:`REQ-${Date.now().toString().slice(-4)}`, type:mode ? 'Course enrollment change' : 'Student service application', submitted:'2026-11-01', status:'pending', note:'Submitted for review' },...current.requests] })); setForm(false); announce('Request submitted. The status tracker was updated.') }} fields={mode ? ['Request type','Course','Reason'] : ['Application type','Purpose','Additional notes']} />}</>
}

function FormDialog({ title, fields, onClose, onSubmit }: { title: string; fields: string[]; onClose: () => void; onSubmit: () => void }) {
  const [values, setValues] = useState<Record<string,string>>({}), [error, setError] = useState('')
  useEffect(() => {
    const close = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose() }
    window.addEventListener('keydown', close)
    return () => window.removeEventListener('keydown', close)
  }, [onClose])
  const submit = (event: FormEvent) => { event.preventDefault(); const missing = fields.find(field => !values[field]?.trim()); if (missing) setError(`${missing} is required.`); else onSubmit() }
  return <div className="overlay" onMouseDown={onClose}><form className="dialog" onMouseDown={event => event.stopPropagation()} onSubmit={submit}><header><div><span className="kicker">ONLINE APPLICATION</span><h2>{title}</h2></div><CloseButton onClick={onClose} label={`Close ${title}`} /></header>{fields.map(field => <label key={field}>{field}{field.toLowerCase().includes('reason') || field.includes('notes') ? <textarea value={values[field] || ''} onChange={event => setValues({...values,[field]:event.target.value})} /> : <input type={field.toLowerCase().includes('date') ? 'date' : 'text'} value={values[field] || ''} onChange={event => setValues({...values,[field]:event.target.value})} />}</label>)}{error && <div className="form-message danger">{error}</div>}<footer><Button variant="secondary" onClick={onClose}>Cancel</Button><Button type="submit">Submit application</Button></footer></form></div>
}

function Documents({ state, update, announce }: PageProps) {
  const input = useRef<HTMLInputElement>(null), [filter, setFilter] = useState('All')
  const shown = state.documents.filter(item => filter === 'All' || item.status === filter)
  const upload = (file?: File) => { if (!file) return; update(current => ({ ...current, documents: [{ id:`D${Date.now()}`,name:file.name,category:'Uploaded',status:'Pending',updated:'Just now' },...current.documents] })); announce(`${file.name} uploaded for verification.`) }
  return <><PageHeader eyebrow="SECURE STORAGE" title="Documents Vault" copy="Upload, preview and track verification of academic and compliance documents." actions={<><select value={filter} onChange={event => setFilter(event.target.value)}><option>All</option><option>Verified</option><option>Pending</option><option>Missing</option></select><Button onClick={() => input.current?.click()}><Icon name="plus" size={16} /> Upload</Button><input ref={input} hidden type="file" onChange={event => upload(event.target.files?.[0])} /></>} /><button className="dropzone" onClick={() => input.current?.click()} onDragOver={event => event.preventDefault()} onDrop={event => { event.preventDefault(); upload(event.dataTransfer.files[0]) }}><Icon name="file" size={28} /><strong>Drop a document here or browse files</strong><span>PDF, JPG or PNG · Maximum 10 MB</span></button><div className="document-grid">{shown.map(item => <Card key={item.id}><div className="document-icon"><Icon name="file" /></div><div><strong title={item.name}>{item.name}</strong><small title={`${item.category} · Updated ${item.updated}`}>{item.category} · Updated {item.updated}</small></div><Badge tone={item.status === 'Verified' ? 'success' : item.status === 'Missing' ? 'danger' : 'warning'}>{item.status}</Badge><Button variant="ghost" onClick={() => item.status === 'Missing' ? input.current?.click() : downloadFile(item.name,`UIT document preview\n${item.name}\nStatus: ${item.status}`)}>{item.status === 'Missing' ? 'Upload' : 'Preview'}</Button></Card>)}</div></>
}

function Notifications({ state, update, navigate }: PageProps) {
  return <><PageHeader eyebrow="COMMUNICATIONS" title="Notifications & Announcements" copy="University notices, academic alerts and portal activity." actions={<Button variant="secondary" onClick={() => update(current => ({ ...current, notifications: current.notifications.map(item => ({...item,read:true})) }))}>Mark all read</Button>} /><div className="notification-center"><Card><SectionHead kicker="INBOX" title="Notifications" />{state.notifications.map(item => <ListRow className={item.read ? '' : 'unread'} key={item.id} leading={<i className="notification-dot" />} title={item.title} description={item.body} trailing={<time>{item.time}</time>} onClick={() => { navigate(item.route); update(current => ({ ...current, notifications: current.notifications.map(note => note.id === item.id ? { ...note, read: true } : note) })) }} />)}</Card><Card><SectionHead kicker="UNIVERSITY NEWS" title="Announcements" />{state.announcements.map(item => <ListRow key={item.id} leading={<time>{new Date(item.date).toLocaleDateString('en', { day: '2-digit', month: 'short' })}</time>} title={item.title} description={item.body} />)}</Card></div></>
}

function Support({ state, update, announce }: PageProps) {
  const [ticket, setTicket] = useState(false), [openFaq, setOpenFaq] = useState(0), faqs = [['How do I reset my password?','Use the recovery flow on the login screen. Verification is sent to your UIT email.'],['When does attendance update?','Attendance is synchronized after the instructor submits each class record.'],['How can I request an installment plan?','Open Payments, choose installment request, and submit supporting details.']]
  return <><PageHeader eyebrow="STUDENT HELP DESK" title="Support & FAQ" copy="Find an answer or create a trackable support ticket." actions={<Button onClick={() => setTicket(true)}><Icon name="plus" size={16} /> New ticket</Button>} /><div className="support-grid"><Card><SectionHead kicker="KNOWLEDGE BASE" title="Frequently asked questions" />{faqs.map((item,index) => <button className="faq" key={item[0]} onClick={() => setOpenFaq(openFaq === index ? -1 : index)}><span><strong>{item[0]}</strong>{openFaq === index && <small>{item[1]}</small>}</span><Icon name="chevron" /></button>)}</Card><Card><SectionHead kicker="YOUR REQUESTS" title="Support tickets" />{state.tickets.map(item => <ListRow key={item.id} title={item.subject} description={`${item.id} · Updated ${item.updated}`} trailing={<Badge tone={statusTone(item.status)}>{item.status}</Badge>} />)}</Card></div>{ticket && <FormDialog title="New support ticket" fields={['Subject','Category','Description']} onClose={() => setTicket(false)} onSubmit={() => { update(current => ({...current,tickets:[{id:`T-${Date.now().toString().slice(-3)}`,subject:'New portal support request',status:'pending',updated:'Just now'},...current.tickets]})); setTicket(false); announce('Support ticket created and added to your tracker.') }} />}</>
}

function Profile({ state, update, announce }: PageProps) {
  const student = state.students[state.activeKind], [editing, setEditing] = useState(false), [phone, setPhone] = useState(student.phone), [guardian, setGuardian] = useState(student.guardian), photo = useRef<HTMLInputElement>(null)
  const save = () => { if (!phone.match(/^\+?[0-9 ]{10,}$/)) return announce('Enter a valid phone number with at least 10 digits.'); update(current => ({...current,students:{...current.students,[current.activeKind]:{...current.students[current.activeKind],phone,guardian}}})); setEditing(false); announce('Profile contact details saved.') }
  return <><PageHeader eyebrow="STUDENT ACCOUNT" title="Student Profile" copy="Your official identity, academic and emergency-contact record." actions={<Button variant={editing ? 'primary' : 'secondary'} onClick={() => editing ? save() : setEditing(true)}>{editing ? 'Save changes' : 'Edit profile'}</Button>} /><Card className="profile-hero"><div className="profile-photo"><span>{student.name.split(' ').map(item=>item[0]).slice(0,2)}</span><button onClick={() => photo.current?.click()}><Icon name="plus" size={15} /></button><input ref={photo} type="file" hidden accept="image/*" onChange={() => announce('Profile photo selected and saved for this demo session.')} /></div><div><Badge tone="success">{student.status}</Badge><h2>{student.name}</h2><p>{student.program} · {student.batch} · Section {student.section}</p></div><div className="profile-cgpa"><span>CGPA</span><strong>{student.cgpa.toFixed(2)}</strong></div></Card><div className="profile-sections"><Card><SectionHead kicker="CONTACT" title="Personal details" /><label>University email<input value={student.email} disabled /></label><label>Phone<input value={phone} onChange={event=>setPhone(event.target.value)} disabled={!editing} /></label><label>Nationality<input value={student.nationality} disabled /></label></Card><Card><SectionHead kicker="EMERGENCY" title="Guardian details" /><label>Guardian name<input value={guardian} onChange={event=>setGuardian(event.target.value)} disabled={!editing} /></label><label>Emergency phone<input defaultValue="+92 321 1234567" disabled={!editing} /></label><Button variant="secondary" onClick={() => announce('Password security form opened in Settings.')}>Change password</Button></Card></div></>
}

function Settings({ state, update, reset, announce }: PageProps & { reset: () => void }) {
  const setPref = <K extends keyof PortalState['preferences']>(key: K, value: PortalState['preferences'][K]) => update(current => ({...current,preferences:{...current.preferences,[key]:value}}))
  return <><PageHeader eyebrow="PORTAL PREFERENCES" title="Settings" copy="Language, interface density, notification preferences and active sessions." /><div className="settings-grid"><Card><SectionHead kicker="APPEARANCE" title="Interface" /><label>Density<select value={state.preferences.density} onChange={event=>setPref('density',event.target.value as 'comfortable'|'compact')}><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></label><label>Language<select value={state.preferences.language} onChange={event=>setPref('language',event.target.value)}><option>English</option><option>اردو</option></select></label></Card><Card><SectionHead kicker="COMMUNICATIONS" title="Notifications" /><Switch label="Email notifications" checked={state.preferences.email} onChange={value=>setPref('email',value)} /><Switch label="SMS deadline alerts" checked={state.preferences.sms} onChange={value=>setPref('sms',value)} /><Switch label="Academic announcements" checked onChange={()=>announce('Academic announcements are mandatory and remain enabled.')} /></Card><Card><SectionHead kicker="SECURITY" title="Active sessions" /><ListRow title="Current browser" description="Karachi, Pakistan · Active now" trailing={<Badge tone="success">Current</Badge>} /><Button variant="secondary" onClick={()=>announce('All other sessions were signed out.')}>Sign out other sessions</Button></Card><Card className="about-card"><SectionHead kicker="ABOUT" title="UIT Student Portal" /><div className="build-stamp"><span>Production build</span><strong>UIT-PORTAL · 2026.11.08</strong><small>React 19 · Vite 8 · Light interface</small></div></Card><Card className="danger-zone"><SectionHead kicker="DEMO CONTROLS" title="Reset demo data" /><p>Restore balances, registration, requests, documents and preferences to their original state.</p><Button variant="danger" onClick={()=>{ reset(); announce('Demo data reset to its original state.') }}>Reset demo data</Button></Card></div></>
}
function International({ state, update, announce, navigate }: PageProps) {
  const student = state.students.international
  const policies = state.policies
  const passportDays = Math.ceil((new Date(student.passportExpiry || '').getTime() - Date.now()) / 86400000)
  const visaDays = Math.ceil((new Date(student.visaExpiry || '').getTime() - Date.now()) / 86400000)
  const checklist = ['Academic transcripts', 'Equivalence / attestation certificate (HEC attested)', 'Passport copy', 'Passport photographs', 'Medical certificate', 'Health insurance', 'Financial proof']
  const [renew, setRenew] = useState(false)
  const completedAcknowledgments = Number(state.acknowledgements.orientation) + Number(state.acknowledgements.conduct)
  return <>
    <PageHeader eyebrow="International student center" title="Compliance & Global Student Services" copy="Visa, passport, insurance, immigration and scholarship requirements in one trusted workspace." actions={<Button variant="secondary" onClick={() => navigate('policies')}>View all policies</Button>} />
    <div className="compliance-score"><Ring value={71} label="Complete" /><div><span>Compliance status</span><h2>2 actions required before examinations</h2><p>Upload health insurance proof and submit visa renewal evidence.</p></div><Button onClick={() => setRenew(true)}>Start visa renewal</Button></div>
    <div className="compliance-grid">
      <Card title="Passport"><StatusLine label={student.passportNo || ''} value={`Expires ${student.passportExpiry}`} status={passportDays < 90 ? 'warning' : 'success'} note={`${passportDays} days remaining · must extend 6 months beyond semester end`} /></Card>
      <Card title="Student visa"><StatusLine label={student.visaType || ''} value={`Expires ${student.visaExpiry}`} status={visaDays < 90 ? 'danger' : 'success'} note={`${visaDays} days remaining · renewal evidence required`} /></Card>
      <Card title="Medical insurance"><StatusLine label={student.insuranceValid ? 'Verified' : 'Proof missing'} value={student.insuranceValid ? 'Valid through 2027' : 'Admit card blocked'} status={student.insuranceValid ? 'success' : 'danger'} note="Coverage is mandatory before exam admit-card release" /><Button variant="secondary" onClick={() => navigate('documents')}>Upload insurance</Button></Card>
      <Card title="Scholarship"><StatusLine label={student.scholarship || ''} value={`Current CGPA ${student.cgpa}`} status={student.cgpa < policies.scholarshipCgpa ? 'danger' : 'success'} note={`Minimum ${policies.scholarshipCgpa.toFixed(1)} CGPA required · currently ${student.cgpa < policies.scholarshipCgpa ? 'at risk' : 'in good standing'}`} /></Card>
    </div>
    <div className="international-lower">
      <Card title="Document checklist" description="Admission and compliance files required by the International Office.">
        <div className="list-row-group">{checklist.map(name => { const document = state.documents.find(item => item.name.toLowerCase().includes(name.split(' ')[0].toLowerCase())); const status = document?.status || 'Required'; return <ListRow key={name} leading={<span className={`check-state ${status === 'Verified' ? 'done' : ''}`}>{status === 'Verified' && <Icon name="check" size={13} />}</span>} title={name} description={document ? `Updated ${document.updated}` : 'Upload this document to complete your file'} trailing={<Badge tone={statusTone(status)}>{status}</Badge>} onClick={() => navigate('documents')} /> })}</div>
      </Card>
      <Card title="Required acknowledgments" description="Complete both acknowledgments before registration review.">
        <div className="list-row-group"><Switch label="International orientation" description="Required first-arrival briefing" checked={state.acknowledgements.orientation} onChange={value => update(current => ({ ...current, acknowledgements: { ...current.acknowledgements, orientation: value } }))} /><Switch label="Student code of conduct" description="University conduct agreement" checked={state.acknowledgements.conduct} onChange={value => update(current => ({ ...current, acknowledgements: { ...current.acknowledgements, conduct: value } }))} /><ListRow title="Local guardian" description={`${student.guardian} · Karachi · Verified emergency contact`} trailing={<Badge tone="success">Complete</Badge>} /></div>
        <div className="card-helper"><span>Acknowledgments complete</span><strong>{completedAcknowledgments} / 2</strong><div className="progress"><i style={{ width: `${completedAcknowledgments * 50}%` }} /></div></div>
      </Card>
    </div>
    {renew && <FormDialog title="Visa renewal request" fields={['Current visa number', 'Expected renewal date', 'Supporting note']} onClose={() => setRenew(false)} onSubmit={() => { update(current => ({ ...current, requests: [{ id: `REQ-${Date.now().toString().slice(-4)}`, type: 'Student visa renewal', submitted: '2026-11-01', status: 'pending', note: 'With International Office' }, ...current.requests] })); setRenew(false); announce('Visa renewal request submitted to the International Office.') }} />}
  </>
}
function StatusLine({label,value,status,note}:{label:string;value:string;status:string;note:string}) {return <div className="status-line"><Badge tone={status}>{status==='success'?'Compliant':'Action required'}</Badge><strong>{label}</strong><span>{value}</span><small>{note}</small></div>}

function Policies({ state, update, announce }: PageProps) {
  const p=state.policies, rules=[['Passport validity',`Passport must remain valid at least ${p.passportBufferMonths} months beyond semester end. Warning begins ${p.passportWarningDays} days before expiry.`],['Visa / residence permit','Expired status blocks course registration. Renewal evidence can be submitted to the International Office.'],['Full-time enrollment',`${p.minCredits} credit hours minimum and ${p.maxCredits} maximum without written approval.`],['Attendance & eligibility',`${p.attendanceMinimum}% minimum attendance in every course for exam eligibility.`],['Academic standing',`CGPA below ${p.probationCgpa.toFixed(1)} results in probation; repeated probation triggers academic review.`],['Academic integrity','Registration requires acknowledgment of plagiarism and academic-integrity rules.'],['Health insurance','Verified health-insurance proof is mandatory before an international admit card is released.'],['Local guardian','International students must keep a verified local guardian and emergency contact on file.'],['Scholarship conditions',`Merit scholarship requires at least ${p.scholarshipCgpa.toFixed(1)} CGPA; lower performance triggers an at-risk review.`],['Late fee',`${p.lateFeePercent}% late fee applies after the published voucher due date.`],['Leave & withdrawal','Add/drop closes November 08; withdrawal closes November 28 and results in a W grade.']]
  return <><PageHeader eyebrow="EDITABLE POLICY CONFIGURATION" title="University Policies" copy="Transparent rules used throughout registration, finance and examination eligibility." actions={<Button variant="secondary" onClick={()=>{downloadFile('UIT-student-policies.txt',rules.map(item=>`${item[0]}\n${item[1]}`).join('\n\n'));announce('Policy summary downloaded.')}}><Icon name="download" size={16}/> Download</Button>} /><div className="policy-layout"><div>{rules.map((item,index)=><Card key={item[0]} className="policy-item"><span>{String(index+1).padStart(2,'0')}</span><div><h3>{item[0]}</h3><p>{item[1]}</p></div></Card>)}</div><Card className="policy-editor"><SectionHead kicker="AUTHORIZED DEMO CONFIG" title="Policy values" />{[['Attendance minimum','attendanceMinimum','%'],['Minimum credit load','minCredits','credits'],['Maximum credit cap','maxCredits','credits'],['Scholarship CGPA','scholarshipCgpa','CGPA'],['Late fee','lateFeePercent','%']].map(([label,key,suffix])=><label key={key}>{label}<div><input type="number" value={p[key as keyof typeof p]} onChange={event=>update(current=>({...current,policies:{...current.policies,[key]:Number(event.target.value)}}))}/><span>{suffix}</span></div></label>)}<Button onClick={()=>announce('Policy values saved and enforcement rules recalculated.')}>Save policy configuration</Button></Card></div></>
}

function NotFound({navigate}:{navigate:(id:string)=>void}) {return <div className="not-found"><Logo variant="full"/><strong>404</strong><h1>This page left the syllabus.</h1><p>The requested portal route does not exist or may have moved.</p><Button onClick={()=>navigate('dashboard')}>Return to dashboard</Button></div>}

export default function App() {
  const { state, update, reset } = usePortalStore()
  const location = useLocation()
  const [ready, setReady] = useState(() => new URLSearchParams(location.search).get('debug') === 'layout')
  useEffect(() => {
    const timer = window.setTimeout(() => setReady(true), 650)
    return () => window.clearTimeout(timer)
  }, [])
  if (!ready) return <LoadingScreen />
  if (location.pathname === '/_kit') return <Kit />
  return state.loggedIn ? <Shell state={state} update={update} reset={reset} /> : <Login state={state} update={update} />
}
